CREATE SCHEMA IF NOT EXISTS posvenda_stage;
CREATE SCHEMA IF NOT EXISTS posvenda;
CREATE TABLE IF NOT EXISTS posvenda.execucao(id uuid PRIMARY KEY,inicio timestamptz DEFAULT now(),fim timestamptz,status text NOT NULL CHECK(status IN ('executando','publicado','falhou')),data_inicio date NOT NULL,data_referencia date NOT NULL,origem text NOT NULL,contagens jsonb);
CREATE TABLE IF NOT EXISTS posvenda.publicacao(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),execucao_id uuid NOT NULL REFERENCES posvenda.execucao(id));
CREATE TABLE IF NOT EXISTS posvenda_stage.documento_fatura (codigo_docfat bigint, empresa_docfat integer, cliente_docfat integer, dtemissao_docfat timestamp without time zone, tipo_docfat smallint, opcao_docfat smallint, entrega_docfat text, localentrega_docfat integer, status_docfat integer, motivo_docfat integer, PRIMARY KEY (codigo_docfat));
CREATE TABLE IF NOT EXISTS posvenda_stage.documento_item (autoinc_docitem bigint, documento_docitem bigint, composicaoitem_docitem bigint, tipo_docitem smallint, item_docitem integer, motivo_docitem integer, tipoassistencia_docitem smallint, PRIMARY KEY (autoinc_docitem));
CREATE TABLE IF NOT EXISTS posvenda_stage.documento_item_detalhe (autoinc_docitemdet bigint, autoincitem_docitemdet bigint, qtdechapas_docitemdet numeric(18,4), qtdeaberta_docitemdet numeric(18,4), qtdefaturado_docitemdet numeric(18,4), qtdecancelado_docitemdet numeric(18,4), vlrbrutoliquido_docitemdet numeric(18,2), cor_docitemdet integer, PRIMARY KEY (autoinc_docitemdet));
CREATE TABLE IF NOT EXISTS posvenda_stage.documento_devolucaocancela (autoinc_docdev bigint, documento_docdev bigint, autoincitemdetdoc_docdev bigint, quantidade_docdev numeric(18,4), motivodevolucao_docdev integer, PRIMARY KEY (autoinc_docdev));
CREATE TABLE IF NOT EXISTS posvenda_stage.documento_entrega_devcan (autoinc_docentdev bigint, documento_docentdev bigint, autoincdocent_docentdev bigint, opcaodocumento_docentdev smallint, qtdechapas_docentdev numeric(18,4), motivo_docentdev integer, PRIMARY KEY (autoinc_docentdev));
CREATE TABLE IF NOT EXISTS posvenda_stage.documento_entrega (autoinc_docent bigint, documento_docent bigint, autoincitemdetdoc_docent bigint, tipo_docent smallint, PRIMARY KEY (autoinc_docent));
CREATE TABLE IF NOT EXISTS posvenda_stage.documento_pedido (documento_docped bigint, dtprevisaofaturamento_docped timestamp without time zone, PRIMARY KEY (documento_docped));
CREATE TABLE IF NOT EXISTS posvenda_stage.motivo (codigo_motivo integer, descricao_motivo text, tipo_motivo smallint, PRIMARY KEY (codigo_motivo));
CREATE TABLE IF NOT EXISTS posvenda_stage.pessoa (codigo_pessoa integer, razaosocial_pessoa text, grupo_pessoa integer, PRIMARY KEY (codigo_pessoa));
CREATE TABLE IF NOT EXISTS posvenda_stage.pessoa_endereco (autoinc_pessoa_end integer, cidade_pessoa_end integer, PRIMARY KEY (autoinc_pessoa_end));
CREATE TABLE IF NOT EXISTS posvenda_stage.item (codigo_item integer, descricao_item text, PRIMARY KEY (codigo_item));
CREATE TABLE IF NOT EXISTS posvenda_stage.cidade (codigo_cidade integer, descricao_cidade text, uf_cidade integer, PRIMARY KEY (codigo_cidade));
CREATE TABLE IF NOT EXISTS posvenda_stage.uf (codigo_uf integer, sigla_uf text, PRIMARY KEY (codigo_uf));
CREATE TABLE IF NOT EXISTS posvenda_stage.status (codigo_status integer, descricao_status text, PRIMARY KEY (codigo_status));
INSERT INTO posvenda.execucao(id,status,data_inicio,data_referencia,origem) VALUES ('${ETL_RUN_ID}','executando','${AFTERSALES_START_DATE}','${AFTERSALES_REFERENCE_DATE}','Cópia local anonimizada / Apache Hop');
TRUNCATE posvenda_stage.documento_fatura, posvenda_stage.documento_item, posvenda_stage.documento_item_detalhe, posvenda_stage.documento_devolucaocancela, posvenda_stage.documento_entrega_devcan, posvenda_stage.documento_entrega, posvenda_stage.documento_pedido, posvenda_stage.motivo, posvenda_stage.pessoa, posvenda_stage.pessoa_endereco, posvenda_stage.item, posvenda_stage.cidade, posvenda_stage.uf, posvenda_stage.status;
